<script setup lang="ts">import {computed} from 'vue';import type {Treatment,Reading} from '../types/domain';const props=defineProps<{treatments:Treatment[];readings:Reading[]}>();const columns=computed(()=>props.treatments.map(t=>({...t,levels:Array.from({length:9},(_,i)=>({grade:9-i,n:props.readings.filter(r=>r.treatment_id===t.id&&r.grade===9-i).length}))})));const colors=['var(--brick)','var(--olive)','var(--clay)','var(--ink)','var(--muted)'];</script><template><div class="grade-chart-scroll"><svg class="grade-chart" :viewBox="`0 0 ${110+treatments.length*135} 470`" role="img" :aria-label="'实际'+readings.length+'份试样等级点阵，每点一份'"><g v-for="grade in 9" :key="grade"><line x1="45" :x2="90+treatments.length*135" :y1="35+(9-grade)*42" :y2="35+(9-grade)*42" stroke="currentColor" opacity=".12"/><text x="25" :y="45+(9-grade)*42" class="grade-tick">{{grade}}</text></g><g v-for="(t,i) in columns" :key="t.id"><text :x="112+i*135" y="430" text-anchor="middle" class="group-label">{{t.code}} {{t.name}}</text><g v-for="level in t.levels" :key="level.grade"><circle v-for="j in level.n" :key="j" :cx="77+i*135+(j-1)%10*7" :cy="40+(9-level.grade)*42+Math.floor((j-1)/10)*8" r="2.5" :fill="colors[i]"><title>{{t.name}} / 等级{{level.grade}} / 此级{{level.n}}份</title></circle></g></g><text x="45" y="465" class="chart-caption">等级类别纵向排列；每个点为独立试样，不把间距解释为性能差。</text></svg></div></template>